const bytes = Buffer.from([0xfb, 0xff]);
console.log(bytes.toString('base64'));    // +/8=
console.log(bytes.toString('base64url')); // -_8

const std = '+/8=';
const url = std.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
console.log(url); // -_8

const back = url.replace(/-/g, '+').replace(/_/g, '/');
const padded = back + '='.repeat((4 - (back.length % 4)) % 4);
